use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;

/// Truncate to at most `max` Unicode scalar values (matching Python's `len`),
/// always cutting on a char boundary.
fn bound_chars(s: String, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => {
            let mut s = s;
            s.truncate(idx);
            s
        }
        None => s,
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let intent = q.intent;

        // The requires-clause guarantees the bound already; enforce it anyway so
        // the ensures-clause holds regardless of what the caller sends.
        let question = bound_chars(q.question, MAX_QUESTION_CHARS);

        let mut knowledge: Vec<String> = kb_read::lookup(&question);

        // `present(knowledge)`: never hand back an empty knowledge set.
        if knowledge.is_empty() {
            knowledge.push(String::from("No relevant knowledge-base entries found."));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
